ee:variables.ee:set-variable:
%dw 2.0
import isoUtc, lowerKeys, nowIso from modules::util
output application/java
var lookbackHours = (vars.settings['audit.max_lookback_hours'] default 24) as Number
var floorDt = now() - ("PT$(lookbackHours)H" as Period)
var last = lowerKeys(vars.lastPoll)[0].window_end_utc
var startDt = if ((last != null) and ((last as DateTime) >= floorDt)) (last as DateTime) else floorDt
---
{
	start: isoUtc(startDt),
	end: nowIso(),
	incremental: (last != null) and ((last as DateTime) >= floorDt)
}

%dw 2.0
output application/java
var total = (payload.total default 0) as Number
var pages = min([ceil(total / vars.pageSize), 50])
---
if (pages <= 1) [] else (1 to pages - 1) map ((i) -> i * vars.pageSize)
